import Ajv from 'ajv';
import { z } from 'zod';
import type { ProfileUsage, ProfileRuntime } from '../../types/design-profile';
import { readNativeImagePaths } from './nativeImages';

const textBlock = z.object({ type: z.literal('text'), text: z.string() });
const content = z.union([z.string(), z.array(textBlock)]);
const modelRequest = z
  .object({
    model: z.string(),
    max_tokens: z.number().positive(),
    stream: z.literal(false).optional(),
    system: content.optional(),
    messages: z
      .array(z.object({ role: z.enum(['user', 'assistant']), content }))
      .min(1),
    output_config: z.object({
      format: z.object({
        type: z.literal('json_schema'),
        schema: z.record(z.string(), z.unknown()),
      }),
    }),
    temperature: z.number().optional(),
    top_p: z.number().optional(),
  })
  .strict();

export interface ProfileAgentResult {
  value: unknown;
  usage: Record<string, unknown>;
  inspectedImages: string[];
}

export const prepareModelRequest = (
  input: unknown,
): { prompt: string; schema: Record<string, unknown> } => {
  const request = modelRequest.parse(input);
  const text = (value: z.infer<typeof content>): string =>
    typeof value === 'string'
      ? value
      : value.map((block) => block.text).join('\n');
  const prompt = [
    request.system ? text(request.system) : '',
    ...request.messages.map(
      (message) => `${message.role}: ${text(message.content)}`,
    ),
  ]
    .filter(Boolean)
    .join('\n\n');
  return { prompt, schema: request.output_config.format.schema };
};

export const validateModelResult = (
  schema: Record<string, unknown>,
  value: unknown,
): unknown => {
  const ajv = new Ajv({
    strict: false,
    validateFormats: false,
    ownProperties: true,
  });
  const validate = ajv.compile(schema);
  if (!validate(value))
    throw new Error('Agent result does not match the requested schema');
  return value;
};

const answerObject = (answer: string): unknown => {
  try {
    return JSON.parse(answer);
  } catch {
    const fences = [...answer.matchAll(/```(?:json)?\s*([\s\S]*?)\s*```/g)];
    if (!answer.includes('```')) {
      const start = answer.indexOf('{');
      const end = answer.lastIndexOf('}');
      if (start >= 0 && end > start)
        return JSON.parse(answer.slice(start, end + 1));
    }
    if (fences.length !== 1 || (answer.match(/```/g) ?? []).length !== 2)
      throw new Error('Agent did not return one unambiguous JSON answer');
    return JSON.parse(fences[0][1]);
  }
};

export const readAgentResult = (
  runtime: ProfileRuntime,
  stdout: string,
  answer?: string,
): ProfileAgentResult => {
  const events: Array<Record<string, unknown>> = stdout
    .split('\n')
    .flatMap((line) => {
      try {
        return [z.record(z.string(), z.unknown()).parse(JSON.parse(line))];
      } catch {
        return [];
      }
    });
  if (
    events.some(
      (event) => event.type === 'turn.failed' || event.is_error === true,
    )
  )
    throw new Error(`${runtime} could not complete the profile task`);
  if (runtime === 'codex') {
    const finished = events.find((event) => event.type === 'turn.completed');
    if (!finished || !answer)
      throw new Error('Codex did not return a completed profile task');
    return {
      value: answerObject(answer),
      usage: z.record(z.string(), z.unknown()).parse(finished.usage ?? {}),
      inspectedImages: [],
    };
  }
  const results = events.filter((event) => event.type === 'result');
  const finished = results[results.length - 1];
  if (!finished)
    throw new Error(`${runtime} did not return a completed profile task`);
  return {
    value:
      finished.structured_output ??
      answerObject(z.string().parse(finished.result)),
    usage: z.record(z.string(), z.unknown()).parse(finished.usage ?? {}),
    inspectedImages: readNativeImagePaths(runtime, events),
  };
};

export const reportedProfileUsage = (
  usage: Record<string, unknown>,
): ProfileUsage => {
  const count = (key: string): number | undefined =>
    typeof usage[key] === 'number' &&
    Number.isFinite(usage[key]) &&
    usage[key] >= 0
      ? usage[key]
      : undefined;
  return {
    inputTokens: count('input_tokens') ?? count('inputTokens'),
    outputTokens: count('output_tokens') ?? count('outputTokens'),
    cachedInputTokens:
      count('cached_input_tokens') ??
      count('cache_read_input_tokens') ??
      count('cacheReadTokens'),
  };
};
